#panel-layer{position:absolute;inset:0;z-index:25;display:flex;align-items:center;justify-content:center;background:rgba(3,6,9,.52);backdrop-filter:blur(3px);padding:26px}
.panel{width:min(560px,94vw);max-height:88vh;display:flex;flex-direction:column;animation:panelIn .22s ease;border-color:rgba(216,184,120,.34)}
.panel.wide{width:min(820px,94vw)}
@keyframes panelIn{from{opacity:0;transform:scale(.985) translateY(8px)}to{opacity:1;transform:none}}
.panel header{display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid rgba(216,184,120,.16);position:relative}
.panel header:after{content:"";position:absolute;left:22px;right:22px;bottom:-1px;height:1px;background:linear-gradient(90deg,transparent,rgba(216,184,120,.5),transparent)}
.panel h3{font-family:var(--font-display);font-size:18px;font-weight:500;letter-spacing:.13em;color:#f1e8d7;text-transform:uppercase}
.close-panel{width:28px;height:28px;border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.5);font-size:11px;transition:.16s}
.close-panel:hover{border-color:rgba(226,104,122,.5);color:#ffc4cc}
.panel-body{padding:20px 22px 24px;overflow-y:auto}
.panel-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:22px}
.panel-actions .btn-ghost,.panel-actions .btn-danger{flex:1;min-width:120px}
.panel-body h4{font-family:var(--font-display);font-size:12px;letter-spacing:.2em;color:var(--gold);text-transform:uppercase;margin:18px 0 10px}
.panel-body h4:first-child{margin-top:0}
.fineprint{font-size:9.5px;color:rgba(255,255,255,.3);line-height:1.6;margin-top:16px;font-weight:300}

/* character */
.char-header{display:flex;gap:16px;align-items:center;padding-bottom:16px;border-bottom:1px solid rgba(255,255,255,.07);margin-bottom:4px}
.char-avatar{width:74px;height:74px;border:1px solid rgba(216,184,120,.35);background:radial-gradient(circle,#1a2028,#0a0e13);display:flex;align-items:center;justify-content:center;font-size:30px;color:var(--gold);font-family:var(--font-display)}
.char-header-info{flex:1}
.char-header-info h2{font-family:var(--font-display);font-size:23px;font-weight:500;color:#f4ebd9}
.char-header-info .path-line{font-size:9px;letter-spacing:.2em;color:var(--gold);text-transform:uppercase;margin-top:3px}
.char-header-info .title-line{font-size:10px;color:var(--muted);margin-top:5px;font-style:italic}
.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:8px}
.stat-box{border:1px solid rgba(255,255,255,.07);padding:10px 12px;background:rgba(255,255,255,.02)}
.stat-box .sb-label{font-size:8px;letter-spacing:.16em;color:var(--muted);text-transform:uppercase}
.stat-box .sb-value{font-family:var(--font-display);font-size:18px;color:#f0e6d2;margin-top:2px}
.attr-row{display:flex;align-items:center;gap:10px;padding:8px 10px;border-bottom:1px solid rgba(255,255,255,.05)}
.attr-row .attr-name{width:90px;font-size:10px;letter-spacing:.14em;color:var(--muted);text-transform:uppercase}
.attr-row .attr-val{width:36px;font-family:var(--font-display);font-size:15px;color:#f1e7d4}
.attr-row .bar{flex:1;height:5px;margin:0}
.attr-row .bar i{background:linear-gradient(90deg,#6c5729,#d8b878)}
.attr-row button{width:20px;height:20px;border:1px solid rgba(216,184,120,.3);color:var(--gold);font-size:12px;line-height:1}
.attr-row button:hover{background:rgba(216,184,120,.16)}
.attr-row .attr-desc{font-size:8.5px;color:rgba(255,255,255,.28);width:88px;text-align:right}
.deed-row{display:flex;justify-content:space-between;font-size:10.5px;padding:5px 0;border-bottom:1px dashed rgba(255,255,255,.06);color:rgba(233,227,214,.7)}
.deed-row b{color:var(--teal);font-weight:500}
.rep-row{display:flex;align-items:center;gap:10px;padding:7px 0;font-size:10.5px}
.rep-row .rep-name{width:120px;color:rgba(233,227,214,.8)}
.rep-row .rep-track{flex:1;height:5px;background:rgba(0,0,0,.5);position:relative;overflow:hidden}
.rep-row .rep-track i{position:absolute;top:0;bottom:0;left:50%;background:linear-gradient(90deg,#5a7f74,#7fe0c8)}
.rep-row .rep-track i.neg{background:linear-gradient(90deg,#a34d59,#e2687a);left:auto;right:50%}
.rep-row .rep-val{width:34px;text-align:right;color:var(--gold);font-size:10px}

/* inventory */
.inv-gold{display:flex;justify-content:space-between;align-items:center;font-size:11px;color:var(--muted);margin-bottom:14px;padding-bottom:10px;border-bottom:1px solid rgba(255,255,255,.07)}
.inv-gold b{color:var(--gold);font-family:var(--font-display);font-size:16px;letter-spacing:.04em}
.inv-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}
.inv-cell{aspect-ratio:1;border:1px solid rgba(255,255,255,.07);background:rgba(255,255,255,.02);position:relative;display:flex;align-items:center;justify-content:center;font-size:19px;cursor:pointer;transition:.14s}
.inv-cell:hover{border-color:rgba(216,184,120,.5);background:rgba(216,184,120,.07);transform:translateY(-1px)}
.inv-cell.empty{cursor:default;opacity:.32}
.inv-cell.empty:hover{border-color:rgba(255,255,255,.07);background:rgba(255,255,255,.02);transform:none}
.inv-cell .qty{position:absolute;bottom:2px;right:3px;font-size:8px;color:rgba(255,255,255,.75);font-weight:600}
.inv-cell .rarity-dot{position:absolute;top:3px;right:3px;width:4px;height:4px;border-radius:50%}
.item-detail{margin-top:14px;border:1px solid rgba(216,184,120,.22);padding:14px;background:rgba(0,0,0,.24);min-height:80px}
.item-detail h4{margin:0 0 4px;font-size:15px;letter-spacing:.04em;font-family:var(--font-display)}
.item-detail .item-type{font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.item-detail .item-desc{font-size:10.5px;color:rgba(233,227,214,.62);line-height:1.6;margin-top:8px;font-weight:300}
.item-stats{display:flex;gap:12px;flex-wrap:wrap;margin-top:8px;font-size:10px;color:var(--teal)}
.item-actions{display:flex;gap:8px;margin-top:12px}
.item-actions button{padding:7px 12px;font-size:9px;letter-spacing:.12em;text-transform:uppercase;border:1px solid rgba(216,184,120,.3);color:var(--gold);background:rgba(216,184,120,.05)}
.item-actions button:hover{background:rgba(216,184,120,.15)}

/* skills */
.skill-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.skill-card{border:1px solid rgba(255,255,255,.08);padding:13px;background:linear-gradient(160deg,rgba(255,255,255,.03),rgba(0,0,0,.15));position:relative;transition:.16s}
.skill-card:hover{border-color:rgba(216,184,120,.4)}
.skill-card.locked{opacity:.5}
.skill-card .sk-top{display:flex;align-items:center;gap:10px}
.skill-card .sk-icon{width:36px;height:36px;border:1px solid rgba(216,184,120,.3);display:flex;align-items:center;justify-content:center;font-size:17px;color:var(--gold);background:rgba(216,184,120,.06)}
.skill-card .sk-name{font-family:var(--font-display);font-size:13px;color:#f0e6d2}
.skill-card .sk-meta{font-size:8px;letter-spacing:.12em;color:var(--muted);text-transform:uppercase;margin-top:2px}
.skill-card .sk-desc{font-size:10px;color:rgba(233,227,214,.55);line-height:1.55;margin-top:8px;font-weight:300}
.skill-card .sk-lvl{position:absolute;top:10px;right:10px;font-size:9px;color:var(--gold)}
.skill-card .sk-req{font-size:9px;color:var(--crimson);margin-top:7px}
.path-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:18px}
.path-card{border:1px solid rgba(255,255,255,.08);padding:10px;text-align:center;background:rgba(255,255,255,.02)}
.path-card b{display:block;font-family:var(--font-display);font-size:11px;letter-spacing:.05em;color:#e9dfcc;margin-top:4px}
.path-card span{font-size:8px;letter-spacing:.1em;color:var(--muted);text-transform:uppercase}
.path-card.owned{border-color:rgba(216,184,120,.5);background:rgba(216,184,120,.08)}
.path-card.secret{border-color:rgba(179,155,255,.35)}
.path-card.secret.owned{border-color:var(--violet);box-shadow:0 0 18px rgba(179,155,255,.15)}
.path-card .pc-glyph{font-size:19px;color:var(--gold)}
.path-card.secret .pc-glyph{color:var(--violet)}
CSSEOF
