/* quests */
.quest-card{border:1px solid rgba(255,255,255,.07);padding:14px;margin-bottom:8px;background:rgba(255,255,255,.02);border-left:2px solid var(--gold)}
.quest-card.done{border-left-color:var(--teal);opacity:.7}
.quest-card .qc-top{display:flex;justify-content:space-between;align-items:baseline}
.quest-card .qc-name{font-family:var(--font-display);font-size:13px;color:#efe5d2}
.quest-card .qc-lvl{font-size:8px;letter-spacing:.14em;color:var(--muted)}
.quest-card .qc-desc{font-size:10px;color:rgba(233,227,214,.55);line-height:1.6;margin-top:6px;font-weight:300}
.quest-card .qc-obj{font-size:10px;color:var(--teal);margin-top:7px}
.quest-card .qc-reward{font-size:9px;color:var(--gold);margin-top:4px;letter-spacing:.04em}
.empty-note{font-size:11px;color:rgba(255,255,255,.35);font-style:italic;padding:8px 0}

/* guild */
.guild-banner{display:flex;align-items:center;gap:14px;padding:14px;border:1px solid rgba(216,184,120,.24);background:linear-gradient(120deg,rgba(216,184,120,.1),transparent);margin-bottom:16px}
.guild-emblem{width:52px;height:52px;border:1px solid rgba(216,184,120,.4);display:flex;align-items:center;justify-content:center;font-size:22px;color:var(--gold);background:rgba(0,0,0,.3)}
.guild-name{font-family:var(--font-display);font-size:18px;color:#f1e7d4}
.guild-sub{font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);margin-top:3px}
.territory-row{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid rgba(255,255,255,.05);font-size:11px}
.territory-row .terr-name{flex:1;color:rgba(233,227,214,.85)}
.territory-row .terr-status{font-size:9px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.territory-row .terr-status.owned{color:var(--teal)}
.territory-row button{padding:4px 9px;font-size:8.5px;letter-spacing:.1em;text-transform:uppercase;border:1px solid rgba(216,184,120,.3);color:var(--gold);background:transparent}
.territory-row button:hover{background:rgba(216,184,120,.14)}
.guild-feed{font-size:10px;line-height:1.9;color:rgba(233,227,214,.55);font-weight:300}
.guild-feed b{color:var(--gold);font-weight:500}

/* codex */
.codex-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.codex-card{border:1px solid rgba(255,255,255,.08);padding:13px;background:rgba(255,255,255,.02);position:relative;overflow:hidden}
.codex-card.found{border-color:rgba(179,155,255,.35);background:linear-gradient(150deg,rgba(179,155,255,.08),rgba(0,0,0,.15))}
.codex-card.found:before{content:"";position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--violet),transparent)}
.codex-card .cx-glyph{font-size:20px;color:rgba(255,255,255,.2)}
.codex-card.found .cx-glyph{color:var(--violet);text-shadow:0 0 14px rgba(179,155,255,.5)}
.codex-card .cx-name{font-family:var(--font-display);font-size:12.5px;color:#e9dfcc;margin-top:7px;letter-spacing:.04em}
.codex-card .cx-desc{font-size:9.5px;color:rgba(233,227,214,.5);line-height:1.55;margin-top:5px;font-weight:300}
.codex-card .cx-hint{font-size:9px;color:rgba(216,184,120,.6);margin-top:7px;font-style:italic}
.codex-card .cx-found-tag{position:absolute;top:10px;right:10px;font-size:7.5px;letter-spacing:.14em;color:var(--violet);border:1px solid rgba(179,155,255,.35);padding:2px 5px}
.codex-card .cx-count{font-size:8px;letter-spacing:.1em;color:rgba(255,255,255,.28);margin-top:6px}

/* map */
.map-body{padding:14px!important;display:flex;flex-direction:column;gap:10px}
#worldmap{width:100%;height:auto;border:1px solid rgba(216,184,120,.18);background:#0b1116;display:block}
.map-legend{display:flex;gap:20px;font-size:9px;color:var(--muted);letter-spacing:.06em;flex-wrap:wrap}
.map-legend i{display:inline-block;width:6px;height:6px;margin-right:5px;border-radius:50%;vertical-align:middle}
.lg.town{background:#e6cd8e}.lg.you{background:#fff;box-shadow:0 0 6px #fff}.lg.poi{background:#7fe0c8}.lg.secret{background:#b39bff}

/* crafting */
.craft-row{display:flex;gap:12px;align-items:center;padding:10px;border-bottom:1px solid rgba(255,255,255,.05)}
.craft-icon{width:36px;height:36px;border:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;font-size:16px;background:rgba(0,0,0,.2)}
.craft-info{flex:1}
.craft-name{font-family:var(--font-display);font-size:12px;color:#ece2d0}
.craft-req{font-size:9px;color:var(--muted);margin-top:3px}
.craft-req .ok{color:var(--teal)}.craft-req .no{color:var(--crimson)}
.craft-row button{padding:7px 13px;font-size:9px;letter-spacing:.1em;text-transform:uppercase;border:1px solid rgba(216,184,120,.35);color:var(--gold);background:rgba(216,184,120,.05)}
.craft-row button:hover{background:rgba(216,184,120,.16)}
.prof-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px}
.prof-card{border:1px solid rgba(255,255,255,.07);padding:9px;text-align:center;background:rgba(255,255,255,.02)}
.prof-card b{display:block;font-size:10px;color:#e9dfcc;margin-top:3px;letter-spacing:.04em}
.prof-card span{font-size:8px;color:var(--muted);text-transform:uppercase;letter-spacing:.1em}
.prof-card em{font-style:normal;display:block;font-size:9px;color:var(--gold);margin-top:4px}
CSSEOF
