/* ============ DIALOGUE ============ */
#dialogue,#shop{position:absolute;inset:0;z-index:30;display:flex;align-items:flex-end;justify-content:center;padding-bottom:170px;pointer-events:none}
.dlg-card,.shop-card{width:min(660px,92vw);pointer-events:auto;animation:dialogIn .22s ease}
@keyframes dialogIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
.dlg-head{display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid rgba(216,184,120,.14)}
.dlg-avatar{width:44px;height:44px;border:1px solid rgba(216,184,120,.32);background:radial-gradient(circle,#212a33,#0a0e13);display:flex;align-items:center;justify-content:center;font-size:18px;color:var(--gold);font-family:var(--font-display)}
.dlg-name{font-family:var(--font-display);font-size:16px;color:#f2e8d5}
.dlg-role{font-size:8.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--gold);margin-top:2px}
.dlg-head .close-panel{margin-left:auto}
.dlg-text{padding:16px 20px;font-size:12.5px;line-height:1.75;color:rgba(233,227,214,.82);font-weight:300;min-height:58px}
.dlg-text em{color:var(--gold);font-style:normal}
.dlg-options{padding:0 18px 18px;display:flex;flex-direction:column;gap:6px}
.dlg-opt{text-align:left;padding:9px 13px;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.02);font-size:11px;color:rgba(233,227,214,.8);transition:.14s}
.dlg-opt:hover{border-color:rgba(216,184,120,.5);background:rgba(216,184,120,.08);color:#fff;padding-left:18px}
.dlg-opt.dim{color:rgba(255,255,255,.32);border-style:dashed}
.dlg-opt .opt-tag{float:right;font-size:8px;letter-spacing:.1em;color:var(--gold);text-transform:uppercase;margin-top:2px}
.dlg-opt .opt-tag.q{color:var(--teal)}

/* shop */
#shop{align-items:center;padding-bottom:0}
.shop-card{width:min(620px,92vw);max-height:80vh;display:flex;flex-direction:column}
.shop-tabs{display:flex;border-bottom:1px solid rgba(255,255,255,.07);padding:0 16px}
.shop-tabs button{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.35);padding:10px 14px;border-bottom:1px solid transparent}
.shop-tabs button.active{color:var(--gold);border-bottom-color:var(--gold)}
.shop-gold{padding:9px 18px;font-size:10px;color:var(--muted);text-align:right}
.shop-gold b{color:var(--gold);font-size:13px}
.shop-list{overflow-y:auto;padding:4px 16px 16px}
.shop-item{display:flex;align-items:center;gap:10px;padding:8px 4px;border-bottom:1px solid rgba(255,255,255,.05)}
.shop-item .si-icon{width:32px;height:32px;border:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.25);font-size:15px}
.shop-item .si-info{flex:1}
.shop-item .si-name{font-size:11.5px;color:#e9dfcc}
.shop-item .si-sub{font-size:8.5px;color:var(--muted);margin-top:2px;letter-spacing:.06em}
.shop-item .si-price{font-size:10px;color:var(--gold);width:64px;text-align:right}
.shop-item button{padding:5px 10px;font-size:8px;letter-spacing:.1em;text-transform:uppercase;border:1px solid rgba(216,184,120,.3);color:var(--gold);margin-left:6px}
.shop-item button:hover{background:rgba(216,184,120,.14)}

/* ============ DISCOVERY / LEVELUP ============ */
#discovery{position:absolute;inset:0;z-index:50;display:flex;align-items:center;justify-content:center;pointer-events:none;background:radial-gradient(ellipse at center,rgba(24,14,46,.45),rgba(3,5,8,.7));animation:discFade 4.6s ease forwards}
@keyframes discFade{0%{opacity:0}8%{opacity:1}82%{opacity:1}100%{opacity:0}}
.disc-inner{text-align:center;max-width:600px;padding:40px;animation:discRise 1s cubic-bezier(.2,.8,.2,1)}
@keyframes discRise{from{opacity:0;transform:translateY(24px) scale(.97)}to{opacity:1;transform:none}}
.disc-kicker{font-size:9px;letter-spacing:.55em;color:var(--violet);text-transform:uppercase}
.disc-glyph{font-size:56px;color:var(--violet);margin:18px 0 8px;text-shadow:0 0 40px rgba(179,155,255,.7);animation:glyphPulse 3s ease infinite}
@keyframes glyphPulse{0%,100%{text-shadow:0 0 30px rgba(179,155,255,.5)}50%{text-shadow:0 0 60px rgba(179,155,255,.95)}}
#disc-title{font-family:var(--font-display);font-size:38px;font-weight:500;letter-spacing:.06em;color:#f6eeda;text-shadow:0 4px 30px rgba(0,0,0,.7)}
#disc-text{font-size:12.5px;color:rgba(233,227,214,.7);line-height:1.8;margin-top:14px;font-weight:300}
#disc-reward{margin-top:20px;font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold)}
#levelup{position:absolute;left:50%;top:32%;transform:translateX(-50%);z-index:22;pointer-events:none;animation:lvlPop 2.6s ease forwards}
@keyframes lvlPop{0%{opacity:0;transform:translate(-50%,12px) scale(.9)}14%{opacity:1;transform:translate(-50%,0) scale(1)}78%{opacity:1}100%{opacity:0;transform:translate(-50%,-18px)}}
.lvl-inner{display:flex;flex-direction:column;align-items:center;gap:2px}
.lvl-inner span{font-size:9px;letter-spacing:.5em;color:var(--gold)}
.lvl-inner b{font-family:var(--font-display);font-size:54px;font-weight:600;color:#f6ecd7;text-shadow:0 0 36px rgba(216,184,120,.7),0 5px 20px #000;line-height:1}
.lvl-inner em{font-style:normal;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:rgba(255,255,255,.5)}

/* loading */
#loading{position:fixed;inset:0;z-index:100;background:#070a0d;flex-direction:column;gap:14px;transition:opacity .8s}
#loading.fade{opacity:0;pointer-events:none}
.load-mark{font-family:var(--font-display);font-size:64px;color:var(--gold);animation:glyphPulse 2.4s infinite;line-height:1}
.load-title{font-family:var(--font-display);font-size:16px;letter-spacing:.6em;color:#efe5d2;padding-left:.6em}
.load-bar{width:260px;height:2px;background:rgba(255,255,255,.1);margin-top:16px;overflow:hidden}
.load-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#8d6f3b,#f0dcae);transition:width .3s ease}
.load-text{font-size:9px;letter-spacing:.3em;text-transform:uppercase;color:rgba(255,255,255,.32)}

/* responsive */
@media (max-width:1100px){
  .chat{display:none}
  .quest-tracker{width:200px}
  .minimap-wrap{width:150px;height:150px}
}
@media (max-width:820px){
  .hud-top{top:12px;left:12px;right:12px}
  .vitals{min-width:0;flex:1;max-width:300px}
  .char-path{display:none}
  .minimap-wrap{width:118px;height:118px;top:96px;right:12px}
