192: .char-avatar{width:74px;height:74px;border:1px solid rgba(216,184,120,.35);background:radial-gradient(circle,#1a2028,#0a0e13);display:flex;align-items:center;justify-content:center;font-size:30px;color:var(--gold);font-family:var(--font-display)}
193: .char-header-info{flex:1}
194: .char-header-info h2{font-family:var(--font-display);font-size:23px;font-weight:500;color:#f4ebd9}
