197: .stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:8px}
198: .stat-box{border:1px solid rgba(255,255,255,.07);padding:10px 12px;background:rgba(255,255,255,.02)}
