271: .guild-banner{display:flex;align-items:center;gap:14px;padding:14px;border:1px solid rgba(216,184,120,.24);background:linear-gradient(120deg,rgba(216,184,120,.1),transparent);margin-bottom:16px}
272: .guild-emblem{width:52px;height:52px;border:1px solid rgba(216,184,120,.4);display:flex;align-items:center;justify-content:center;font-size:22px;color:var(--gold);background:rgba(0,0,0,.3)}
273: .guild-name{font-family:var(--font-display);font-size:18px;color:#f1e7d4}
274: .guild-sub{font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);margin-top:3px}
275: .territory-row{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid rgba(255,255,255,.05);font-size:11px}
276: .territory-row .terr-name{flex:1;color:rgba(233,227,214,.85)}
277: .territory-row .terr-status{font-size:9px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
278: .territory-row .terr-status.owned{color:var(--teal)}
279: .territory-row button{padding:4px 9px;font-size:8.5px;letter-spacing:.1em;text-transform:uppercase;border:1px solid rgba(216,184,120,.3);color:var(--gold);background:transparent}
280: .territory-row button:hover{background:rgba(216,184,120,.14)}
281: .guild-feed{font-size:10px;line-height:1.9;color:rgba(233,227,214,.55);font-weight:300}
282: .guild-feed b{color:var(--gold);font-weight:500}
283: 
284: /* codex */
285: .codex-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
286: .codex-card{border:1px solid rgba(255,255,255,.08);padding:13px;background:rgba(255,255,255,.02);position:relative;overflow:hidden}
287: .codex-card.found{border-color:rgba(179,155,255,.35);background:linear-gradient(150deg,rgba(179,155,255,.08),rgba(0,0,0,.15))}
288: .codex-card.found:before{content:"";position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--violet),transparent)}
289: .codex-card .cx-glyph{font-size:20px;color:rgba(255,255,255,.2)}
290: .codex-card.found .cx-glyph{color:var(--violet);text-shadow:0 0 14px rgba(179,155,255,.5)}
291: .codex-card .cx-name{font-family:var(--font-display);font-size:12.5px;color:#e9dfcc;margin-top:7px;letter-spacing:.04em}
292: .codex-card .cx-desc{font-size:9.5px;color:rgba(233,227,214,.5);line-height:1.55;margin-top:5px;font-weight:300}
293: .codex-card .cx-hint{font-size:9px;color:rgba(216,184,120,.6);margin-top:7px;font-style:italic}
294: .codex-card .cx-found-tag{position:absolute;top:10px;right:10px;font-size:7.5px;letter-spacing:.14em;color:var(--violet);border:1px solid rgba(179,155,255,.35);padding:2px 5px}
295: .codex-card .cx-count{font-size:8px;letter-spacing:.1em;color:rgba(255,255,255,.28);margin-top:6px}
296: 
297: /* map */
298: .map-body{padding:14px!important;display:flex;flex-direction:column;gap:10px}
299: #worldmap{width:100%;height:auto;border:1px solid rgba(216,184,120,.18);background:#0b1116;display:block}
300: .map-legend{display:flex;gap:20px;font-size:9px;color:var(--muted);letter-spacing:.06em;flex-wrap:wrap}
301: .map-legend i{display:inline-block;width:6px;height:6px;margin-right:5px;border-radius:50%;vertical-align:middle}
302: .lg.town{background:#e6cd8e}.lg.you{background:#fff;box-shadow:0 0 6px #fff}.lg.poi{background:#7fe0c8}.lg.secret{background:#b39bff}
303: 
304: /* crafting */
305: .craft-row{display:flex;gap:12px;align-items:center;padding:10px;border-bottom:1px solid rgba(255,255,255,.05)}
306: .craft-icon{width:36px;height:36px;border:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;font-size:16px;background:rgba(0,0,0,.2)}
307: .craft-info{flex:1}
308: .craft-name{font-family:var(--font-display);font-size:12px;color:#ece2d0}
309: .craft-req{font-size:9px;color:var(--muted);margin-top:3px}
310: .craft-req .ok{color:var(--teal)}.craft-req .no{color:var(--crimson)}
311: .craft-row button{padding:7px 13px;font-size:9px;letter-spacing:.1em;text-transform:uppercase;border:1px solid rgba(216,184,120,.35);color:var(--gold);background:rgba(216,184,120,.05)}
312: .craft-row button:hover{background:rgba(216,184,120,.16)}
313: .prof-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px}
314: .prof-card{border:1px solid rgba(255,255,255,.07);padding:9px;text-align:center;background:rgba(255,255,255,.02)}
315: .prof-card b{display:block;font-size:10px;color:#e9dfcc;margin-top:3px;letter-spacing:.04em}
316: .prof-card span{font-size:8px;color:var(--muted);text-transform:uppercase;letter-spacing:.1em}
317: .prof-card em{font-style:normal;display:block;font-size:9px;color:var(--gold);margin-top:4px}
318: 
319: /* ============ DIALOGUE ============ */
320: #dialogue,#shop{position:absolute;inset:0;z-index:30;display:flex;align-items:flex-end;justify-content:center;padding-bottom:170px;pointer-events:none}
321: .dlg-card,.shop-card{width:min(660px,92vw);pointer-events:auto;animation:dialogIn .22s ease}
322: @keyframes dialogIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
323: .dlg-head{display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid rgba(216,184,120,.14)}
324: .dlg-avatar{width:44px;height:44px;border:1px solid rgba(216,184,120,.32);background:radial-gradient(circle,#212a33,#0a0e13);display:flex;align-items:center;justify-content:center;font-size:18px;color:var(--gold);font-family:var(--font-display)}
325: .dlg-name{font-family:var(--font-display);font-size:16px;color:#f2e8d5}
326: .dlg-role{font-size:8.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--gold);margin-top:2px}
327: .dlg-head .close-panel{margin-left:auto}
328: .dlg-text{padding:16px 20px;font-size:12.5px;line-height:1.75;color:rgba(233,227,214,.82);font-weight:300;min-height:58px}
329: .dlg-text em{color:var(--gold);font-style:normal}
330: .dlg-options{padding:0 18px 18px;display:flex;flex-direction:column;gap:6px}
331: .dlg-opt{text-align:left;padding:9px 13px;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.02);font-size:11px;color:rgba(233,227,214,.8);transition:.14s}
332: .dlg-opt:hover{border-color:rgba(216,184,120,.5);background:rgba(216,184,120,.08);color:#fff;padding-left:18px}
333: .dlg-opt.dim{color:rgba(255,255,255,.32);border-style:dashed}
334: .dlg-opt .opt-tag{float:right;font-size:8px;letter-spacing:.1em;color:var(--gold);text-transform:uppercase;margin-top:2px}
335: .dlg-opt .opt-tag.q{color:var(--teal)}
336: 
337: /* shop */
338: #shop{align-items:center;padding-bottom:0}
339: .shop-card{width:min(620px,92vw);max-height:80vh;display:flex;flex-direction:column}
340: .shop-tabs{display:flex;border-bottom:1px solid rgba(255,255,255,.07);padding:0 16px}
341: .shop-tabs button{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.35);padding:10px 14px;border-bottom:1px solid transparent}
342: .shop-tabs button.active{color:var(--gold);border-bottom-color:var(--gold)}
343: .shop-gold{padding:9px 18px;font-size:10px;color:var(--muted);text-align:right}
344: .shop-gold b{color:var(--gold);font-size:13px}
345: .shop-list{overflow-y:auto;padding:4px 16px 16px}
346: .shop-item{display:flex;align-items:center;gap:10px;padding:8px 4px;border-bottom:1px solid rgba(255,255,255,.05)}
347: .shop-item .si-icon{width:32px;height:32px;border:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.25);font-size:15px}
348: .shop-item .si-info{flex:1}
349: .shop-item .si-name{font-size:11.5px;color:#e9dfcc}
350: .shop-item .si-sub{font-size:8.5px;color:var(--muted);margin-top:2px;letter-spacing:.06em}
351: .shop-item .si-price{font-size:10px;color:var(--gold);width:64px;text-align:right}
352: .shop-item button{padding:5px 10px;font-size:8px;letter-spacing:.1em;text-transform:uppercase;border:1px solid rgba(216,184,120,.3);color:var(--gold);margin-left:6px}
353: .shop-item button:hover{background:rgba(216,184,120,.14)}
354: 
355: /* ============ DISCOVERY / LEVELUP ============ */
356: #discovery{position:absolute;inset:0;z-index:50;display:flex;align-items:center;justify-content:center;pointer-events:none;background:radial-gradient(ellipse at center,rgba(24,14,46,.45),rgba(3,5,8,.7));animation:discFade 4.6s ease forwards}
357: @keyframes discFade{0%{opacity:0}8%{opacity:1}82%{opacity:1}100%{opacity:0}}
358: .disc-inner{text-align:center;max-width:600px;padding:40px;animation:discRise 1s cubic-bezier(.2,.8,.2,1)}
359: @keyframes discRise{from{opacity:0;transform:translateY(24px) scale(.97)}to{opacity:1;transform:none}}
360: .disc-kicker{font-size:9px;letter-spacing:.55em;color:var(--violet);text-transform:uppercase}
361: .disc-glyph{font-size:56px;color:var(--violet);margin:18px 0 8px;text-shadow:0 0 40px rgba(179,155,255,.7);animation:glyphPulse 3s ease infinite}
362: @keyframes glyphPulse{0%,100%{text-shadow:0 0 30px rgba(179,155,255,.5)}50%{text-shadow:0 0 60px rgba(179,155,255,.95)}}
363: #disc-title{font-family:var(--font-display);font-size:38px;font-weight:500;letter-spacing:.06em;color:#f6eeda;text-shadow:0 4px 30px rgba(0,0,0,.7)}
364: #disc-text{font-size:12.5px;color:rgba(233,227,214,.7);line-height:1.8;margin-top:14px;font-weight:300}
365: #disc-reward{margin-top:20px;font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold)}
366: #levelup{position:absolute;left:50%;top:32%;transform:translateX(-50%);z-index:22;pointer-events:none;animation:lvlPop 2.6s ease forwards}
367: @keyframes lvlPop{0%{opacity:0;transform:translate(-50%,12px) scale(.9)}14%{opacity:1;transform:translate(-50%,0) scale(1)}78%{opacity:1}100%{opacity:0;transform:translate(-50%,-18px)}}
368: .lvl-inner{display:flex;flex-direction:column;align-items:center;gap:2px}
369: .lvl-inner span{font-size:9px;letter-spacing:.5em;color:var(--gold)}
370: .lvl-inner b{font-family:var(--font-display);font-size:54px;font-weight:600;color:#f6ecd7;text-shadow:0 0 36px rgba(216,184,120,.7),0 5px 20px #000;line-height:1}
371: .lvl-inner em{font-style:normal;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:rgba(255,255,255,.5)}
372: 
373: /* loading */
374: #loading{position:fixed;inset:0;z-index:100;background:#070a0d;flex-direction:column;gap:14px;transition:opacity .8s}
375: #loading.fade{opacity:0;pointer-events:none}
376: .load-mark{font-family:var(--font-display);font-size:64px;color:var(--gold);animation:glyphPulse 2.4s infinite;line-height:1}
377: .load-title{font-family:var(--font-display);font-size:16px;letter-spacing:.6em;color:#efe5d2;padding-left:.6em}
378: .load-bar{width:260px;height:2px;background:rgba(255,255,255,.1);margin-top:16px;overflow:hidden}
379: .load-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#8d6f3b,#f0dcae);transition:width .3s ease}
380: .load-text{font-size:9px;letter-spacing:.3em;text-transform:uppercase;color:rgba(255,255,255,.32)}
381: 
382: /* responsive */
383: @media (max-width:1100px){
384:   .chat{display:none}
385:   .quest-tracker{width:200px}
386:   .minimap-wrap{width:150px;height:150px}
387: }
388: @media (max-width:820px){
389:   .hud-top{top:12px;left:12px;right:12px}
390:   .vitals{min-width:0;flex:1;max-width:300px}
391:   .char-path{display:none}
392:   .minimap-wrap{width:118px;height:118px;top:96px;right:12px}
393:   .quest-tracker{display:none}
394:   .top-actions{top:12px;transform:translateY(60px)}
395:   .icon-btn{width:27px;height:27px;font-size:11px}
396:   .hotbar-wrap{bottom:12px}
397:   .slot{width:38px;height:38px}.slot-icon{font-size:15px}.weapon-slot{width:42px}
398:   .hint-row{display:none}
399:   .title-inner{padding:20px}.game-title{font-size:60px}
400:   .cp-body{grid-template-columns:1fr}.cp-right{display:none}
401:   .creation-panel{max-height:94vh}
402: }

