  const origin=ORIGINS[state.origin]||ORIGINS.blade;state.stats={...origin.stats};state.skillList=[...origin.skills];state.equipped.weapon=origin.weapon;
  if(!load){state.level=1;state.xp=0;state.xpNext=100;state.hp=100+(state.origin==='hearth'?20:0);state.maxHp=state.hp;state.mp=state.origin==='arcane'?90:60;state.maxMp=state.mp;state.stamina=100;state.gold=34;state.inventory={ [origin.weapon]:1,hp_potion:3,wolf_pelt:1,iron_ore:2,moonpetal:1 };state.equipped={weapon:origin.weapon,armor:null,trinket:null};state.deeds={kills:0,distance:0,tames:0,storms:0,dungeons:0,bossKills:0,c crafts:0,melee:0,spells:0,dodges:0,healed:0,talks:0};}
  const seed=$('seed-input')?.value.trim()||state.seed||'AURORA';setupWorld(seed);
  show('title-screen',false);show('creation-screen',false);show('loading',false);show('hud',true);started=true;gameTime=0;lastPlayerPos=player.clone();
  if(!load){state.activeQuest=0;log(`The road opens before ${state.name}.`);toast('The Unbound',`Welcome to ${state.seed}.`);}
  refreshUI();animate();
}

